package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.thieving.*;import io.xeros.content.items.UseItem;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.entity.npc.*;import io.xeros.content.achievement_diary.impl.*;import java.lang.reflect.*;import java.util.*;
public final class GlovesOfSilenceCheck {
 static void need(boolean b,String s){RabbitHuntingCheck.need(b,s);}static void give(Player p,int id,int n){RabbitHuntingCheck.give(p,id,n);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 static Player actor(){Player p=RabbitHuntingCheck.actor();RabbitHuntingCheck.at(p,3280,3398);p.playerLevel[21]=54;p.playerXP[21]=p.getPA().getXPForLevel(54);p.playerLevel[17]=1;p.playerXP[17]=0;give(p,10075,2);need(p.getItems().equipItem(10075,p.getItems().getInventoryItemSlot(10075)),"Equip Hunter54 gloves");return p;}
 static void fail(Player p)throws Exception{set(p.getThieving(),"lastInteraction",0L);set(p.getThieving(),"stunnedUntil",0L);set(p.getThieving(),"successRoll",(java.util.function.DoubleSupplier)()->.999999);p.getHealth().reset();NPC n=Arrays.stream(NPCHandler.npcs).filter(Objects::nonNull).filter(x->!x.isDead()&&x.getName().equalsIgnoreCase("Man")).findFirst().orElseThrow();int oldX=n.absX,oldY=n.absY,oldHeight=n.heightLevel;try{n.absX=p.absX;n.absY=p.absY;n.heightLevel=p.heightLevel;p.getThieving().steal(Thieving.Pickpocket.MAN,n);}finally{n.absX=oldX;n.absY=oldY;n.heightLevel=oldHeight;}}
 static void wearAndCurve(){
  Player p=RabbitHuntingCheck.actor();give(p,10075,1);p.playerXP[21]=p.getPA().getXPForLevel(53);p.playerLevel[21]=99;need(!p.getItems().equipItem(10075,p.getItems().getInventoryItemSlot(10075)),"Boost bypassed baseHunter54");p.playerXP[21]=p.getPA().getXPForLevel(54);p.playerLevel[21]=1;need(p.getItems().equipItem(10075,p.getItems().getInventoryItemSlot(10075)),"Drained Hunter54 should equip");
  need(Math.abs(GlovesOfSilence.chance(p,.55)-.5725)<1e-12,"5% reduction of FAILURE, not5 percentage points");p.getItems().unequipItem(10075,Player.playerHands);need(Math.abs(GlovesOfSilence.chance(p,.55)-.55)<1e-12,"Unworn gloves affected chance");
  System.out.println("SILENCE_BASE_HUNTER54_UNBOOSTABLE_DRAINED_WEAR_REAL_EQUIP_FAILURE_REDUCTION_5_PERCENT_AND_UNWORN_NO_EFFECT_PASS");
 }
 static void lifecycle()throws Exception{
  Player p=actor();int[]xp=p.playerXP.clone();for(int i=1;i<=61;i++){fail(p);need(p.silenceGloveFailures==i&&p.playerEquipment[Player.playerHands]==10075&&count(p,10075)==1,"Real failed pickpocket condition "+i);}fail(p);need(p.silenceGloveFailures==0&&p.playerEquipment[Player.playerHands]==-1&&count(p,10075)==1,"62nd failure must break only WORN pair and reset shared condition");need(Arrays.equals(xp,p.playerXP),"Failed pickpockets awarded XP");
  need(p.getItems().equipItem(10075,p.getItems().getInventoryItemSlot(10075)),"Wear spare pair");fail(p);need(p.silenceGloveFailures==1,"Spare condition not reset after destruction");p.getItems().unequipItem(10075,Player.playerHands);give(p,10075,1);need(p.silenceGloveFailures==1,"Obtaining new pair reset character condition");need(p.getItems().equipItem(10075,p.getItems().getInventoryItemSlot(10075)),"Equip different pair");fail(p);need(p.silenceGloveFailures==2,"Condition not shared across pairs");
  p.getThieving().steal(Thieving.Pickpocket.MAN,null);need(p.silenceGloveFailures==2,"Refused attempt degraded");
  System.out.println("SILENCE62_REAL_FAILED_PICKPOCKETS_BREAK_ONLY_WORN_PAIR_SPARE_SHARED_CONDITION_NEW_PAIR_NO_RESET_NO_XP_OR_REFUSED_DEGRADE_PASS");
 }
 static void diaries()throws Exception{
  Player p=actor();p.getDiaryManager().getArdougneDiary().getMedium().forEach(x->p.getDiaryManager().getArdougneDiary().complete(x));
  RabbitHuntingCheck.at(p,2660,3305);need(GlovesOfSilence.diaryBonus(p)&&Math.abs(GlovesOfSilence.chance(p,.55)-.595)<1e-12,"Medium Ardougne 10% failure reduction not stacked");fail(p);need(p.silenceGloveFailures==0,"Medium diary inArdougne degraded");RabbitHuntingCheck.at(p,3280,3398);need(!GlovesOfSilence.diaryBonus(p),"Medium applied globally");fail(p);need(p.silenceGloveFailures==1,"Medium outsideArdougne should usegloves");p.getDiaryManager().getArdougneDiary().getHard().forEach(x->p.getDiaryManager().getArdougneDiary().complete(x));need(GlovesOfSilence.diaryBonus(p),"Hard notglobal");fail(p);need(p.silenceGloveFailures==1&&Math.abs(GlovesOfSilence.chance(p,.55)-.595)<1e-12,"Hard noStack or noDegrade");p.getItems().unequipItem(10075,Player.playerHands);need(Math.abs(GlovesOfSilence.chance(p,.55)-.595)<1e-12,"Diary needs neither gloves nor cloak");
  System.out.println("SILENCE_ARDOUGNE_MEDIUM_LOCAL_HARD_GLOBAL_NO_CLOAK_NO_STACK_10_PERCENT_FAILURE_BONUS_AND_NO_DEGRADE_PASS");
 }
 static void repairAndSave()throws Exception{
  for(boolean reverse:new boolean[]{false,true}){Player p=actor();p.getItems().unequipItem(10075,Player.playerHands);p.silenceGloveFailures=61;p.playerLevel[12]=63;give(p,10115,1);give(p,1734,1);give(p,946,1);give(p,1733,1);int[]xp=p.playerXP.clone();int a=reverse?10115:10075,b=reverse?10075:10115;UseItem.ItemonItem(p,a,b,p.getItems().getInventoryItemSlot(a),p.getItems().getInventoryItemSlot(b));need(p.silenceGloveFailures==61&&count(p,10115)==1&&count(p,1734)==1,"Craft63 repair consumedmaterials");p.playerLevel[12]=64;UseItem.ItemonItem(p,a,b,p.getItems().getInventoryItemSlot(a),p.getItems().getInventoryItemSlot(b));need(p.silenceGloveFailures==0&&count(p,10115)==0&&count(p,1734)==0&&count(p,10075)==2&&count(p,946)==1&&count(p,1733)==1&&Arrays.equals(xp,p.playerXP),"Craft64 boost repair exactfur/thread tools retained noXP bothorders");}
  for(int tool:new int[]{1734,946,1733}){Player p=actor();p.silenceGloveFailures=30;p.getItems().unequipItem(10075,Player.playerHands);p.playerLevel[12]=64;give(p,10115,1);for(int x:new int[]{1734,946,1733})if(x!=tool)give(p,x,1);GlovesOfSilence.repair(p,10115,10075);need(p.silenceGloveFailures==30&&count(p,10115)==1,"Missing tool/thread consumed material "+tool);}
  Player p=actor();p.silenceGloveFailures=43;p.setLoginName("silenceqa");p.setDisplayName("Silenceqa");p.setIndex(1);p.saveCharacter=true;p.isActive=true;PlayerHandler.players[1]=p;need(PlayerSave.saveGameInstant(p),"Condition save");Player loaded=SkillsAuditCheck.actor();need(PlayerSave.loadGame(loaded,"silenceqa","IsolatedAudit",true).toString().equals("SUCCESS")&&loaded.silenceGloveFailures==43&&loaded.playerEquipment[Player.playerHands]==10075&&count(loaded,10075)==1,"Condition/equipment/spare realreload");PlayerHandler.players[1]=null;
  System.out.println("SILENCE_REAL_ITEMONITEM_BOTH_ORDERS_BOOSTABLE_CRAFT64_ONE_FUR_THREAD_REUSABLE_KNIFE_NEEDLE_NO_XP_MISSING_TOOLS_ATOMIC_REAL_SAVE_RELOAD_PASS");
 }
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;wearAndCurve();lifecycle();diaries();repairAndSave();System.exit(0);}
}
